  r record; def text; nd text; i int; n_fn int := 0;
begin
  for r in
    select p.oid, p.proname from pg_proc p join pg_namespace s on s.oid = p.pronamespace
    where s.nspname = 'public' and p.prokind in ('f', 'p')
      and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  loop
    def := pg_get_functiondef(r.oid); nd := def;
    for i in 1 .. array_length(pairs, 1) loop
      if position(pairs[i][1] in nd) > 0 then nd := replace(nd, pairs[i][1], pairs[i][2]); end if;
    end loop;
    if nd <> def then execute nd; n_fn := n_fn + 1; end if;
  end loop;
  raise notice '168: اتعدّلت رسائل % دالة', n_fn;
end $mig$;
